def backfill_payments(apps, schema_editor):
    """
    One ProjectPayment per payment already taken: online payment requests marked PAID, and
    office-recorded payments, which until now only existed as a history line
    ("Payment received: ₱1,500.00 (balance …)").
    """
    import re
    from decimal import Decimal
    ProjectPayment = apps.get_model('library', 'ProjectPayment')
    ProjectPaymentRequest = apps.get_model('library', 'ProjectPaymentRequest')
    ProjectHistoryLog = apps.get_model('library', 'ProjectHistoryLog')
    for req in ProjectPaymentRequest.objects.filter(status='PAID'):
        ProjectPayment.objects.get_or_create(request=req, defaults={
            'project_id': req.project_id, 'amount': req.amount, 'method': 'online', 'note': req.label,
            'paid_at': req.paid_at or req.created_at})
    pattern = re.compile(r'^Payment received: ₱([\d,]+\.\d{2})')
    for log in ProjectHistoryLog.objects.filter(remarks__startswith='Payment received: '):
        m = pattern.match(log.remarks)
        if m:
            note = log.remarks.split(' — ', 1)[1][:300] if ' — ' in log.remarks else ''
            ProjectPayment.objects.create(project_id=log.project_id, amount=Decimal(m.group(1).replace(',', '')),
                                          method='other', received_by_id=log.trigger_user_id, paid_at=log.timestamp,
                                          note=note or 'Recorded before payment methods were tracked')


def backfill_refund_dates(apps, schema_editor):
    """Refunds marked since the activity log started carry their date there."""
    Order = apps.get_model('library', 'Order')
    ActivityLog = apps.get_model('library', 'ActivityLog')
    for entry in ActivityLog.objects.filter(action='order_refunded'):
        order_id = (entry.details or {}).get('order')
        if order_id:
            Order.objects.filter(pk=order_id, refunded_at__isnull=True).update(refunded_at=entry.created_at)


